// Loads third-party libraries from the CDN (pinned + SRI) and falls back to the
// copies in /vendor if the CDN is unreachable or blocked. Classic script so it
// can start fetching CSS before the app module runs.
// Library list comes from js/vendor-manifest.js (generated by scripts/fetch-vendor.py).
(function () {
  'use strict';
  var libs = window.VENDOR_LIBS || [];
  var localOnly = false;
  try {
    var saved = JSON.parse(localStorage.getItem('fretboard-progressions:v1') || 'null');
    localOnly = !!(saved && saved.settings && saved.settings.localLibsOnly);
  } catch (e) { /* storage unavailable: use CDN */ }
  if (location.protocol === 'file:') localOnly = true;

  var report = window.VENDOR_REPORT = {};

  function loadCss(lib) {
    return new Promise(function (resolve) {
      var link = document.createElement('link');
      link.rel = 'stylesheet';
      var useLocal = function () {
        report[lib.name] = 'local';
        link.onerror = function () { report[lib.name] = 'failed'; resolve(false); };
        link.onload = function () { resolve(true); };
        link.removeAttribute('integrity');
        link.removeAttribute('crossorigin');
        link.href = lib.local;
      };
      link.onload = function () { report[lib.name] = localOnly ? 'local' : 'cdn'; resolve(true); };
      if (localOnly) { link.href = lib.local; link.onerror = function () { report[lib.name] = 'failed'; resolve(false); }; }
      else {
        link.integrity = lib.integrity;
        link.crossOrigin = 'anonymous';
        link.href = lib.cdn;
        link.onerror = useLocal;
      }
      // keep app.css last so it can override
      var anchor = document.getElementById('app-css');
      document.head.insertBefore(link, anchor);
    });
  }

  function loadScript(src, integrity) {
    return new Promise(function (resolve, reject) {
      var s = document.createElement('script');
      s.src = src;
      s.async = false;
      if (integrity) { s.integrity = integrity; s.crossOrigin = 'anonymous'; }
      s.onload = function () { resolve(); };
      s.onerror = function () { s.remove(); reject(new Error('load failed: ' + src)); };
      document.head.appendChild(s);
    });
  }

  function loadJs(lib) {
    var ok = function (where) { return function () { report[lib.name] = where; return true; }; };
    var local = function () {
      return loadScript(lib.local).then(ok('local'), function () { report[lib.name] = 'failed'; return false; });
    };
    if (localOnly) return local();
    return loadScript(lib.cdn, lib.integrity).then(ok('cdn'), local);
  }

  var css = libs.filter(function (l) { return l.type === 'css'; }).map(loadCss);
  var js = libs.filter(function (l) { return l.type === 'js'; }).map(loadJs);
  window.vendorReady = Promise.all(css.concat(js)).then(function () { return report; });
})();
